import React, { useState } from 'react';

export default function StudentDashboard({ userName, userUsername, grade, subjects, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // 🟢 App.js එකෙන් ආපු විෂයන් ටික වෙන් කරගන්නවා
  const enrolledSubjectsList = subjects ? subjects.split(',') : [];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '25px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 4px 15px rgba(21,128,61,0.2)' }}>
              <div>
                <h1 style={{ margin: '0 0 8px 0', fontSize: '28px' }}>Welcome back, {userName}! 👋</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: '15px' }}>Your Aura Pen Saku Learning Portal is ready.</p>
              </div>
              <div style={{ backgroundColor: 'rgba(255,255,255,0.15)', padding: '15px 25px', borderRadius: '12px', textAlign: 'center' }}>
                <h3 style={{ margin: '0 0 5px 0', color: '#facc15', fontSize: '22px' }}>⭐⭐⭐</h3>
                <p style={{ margin: 0, fontSize: '13px', fontWeight: 'bold' }}>3 Star Badges Earned!</p>
              </div>
            </div>

            <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '20px' }}>📚 My Enrolled Classes</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
              
              {/* 🟢 ළමයාගේ ඇත්ත විෂයන් ටික මෙතනින් පෙන්නනවා */}
              {enrolledSubjectsList.length > 0 ? enrolledSubjectsList.map((sub, index) => (
                <div key={index} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderTop: `5px solid #15803d`, display: 'flex', flexDirection: 'column' }}>
                  <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>{grade}</div>
                  <h3 style={{ margin: '0 0 15px 0', color: '#1e293b', fontSize: '18px' }}>{sub.trim()}</h3>
                  <button onClick={() => setActiveTab('lessons')} style={{ width: '100%', padding: '10px', backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>📂 Enter Class</button>
                </div>
              )) : (
                <p style={{ color: '#64748b' }}>No subjects enrolled yet.</p>
              )}
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>👤 My Profile & Security</h2>
            <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
                
                {/* 🟢 ඇත්ත Profile විස්තර */}
                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ margin: '0 0 20px 0', color: '#15803d', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>Personal Details</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div><label style={labelStyle}>Full Name</label><div style={readOnlyStyle}>{userName}</div></div>
                        <div><label style={labelStyle}>Username</label><div style={readOnlyStyle}>{userUsername}</div></div>
                        <div><label style={labelStyle}>Grade / Batch</label><div style={readOnlyStyle}>{grade}</div></div>
                        <div><label style={labelStyle}>Enrolled Subjects</label><div style={readOnlyStyle}>{subjects}</div></div>
                    </div>
                </div>

                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ margin: '0 0 20px 0', color: '#ef4444', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>🔑 Change Password</h3>
                    <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <input type="password" placeholder="Current Password" style={inputStyle} />
                        <input type="password" placeholder="New Password" style={inputStyle} />
                        <input type="password" placeholder="Confirm New Password" style={inputStyle} />
                        <button type="button" style={{ padding: '12px', backgroundColor: '#1e293b', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Update Password</button>
                    </form>
                </div>
            </div>
          </div>
        );

      // (මෙහි lessons, quizzes, forum, feedback ටැබ්ස් කලින් කෝඩ් එකේ විදිහටම තියන්න)
      default: return <div>Select a tab</div>;
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '0 25px', marginBottom: '30px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'lessons'} onClick={() => setActiveTab('lessons')} icon="📺" text="My Lessons" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile" />
        </div>
        
        {/* 🟢 Solid Red Logout Button (හරිම එක) */}
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
          <button onClick={handleLogout} style={{ width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px', display: 'flex', justifyContent: 'center', gap: '10px' }}>
            🚪 Logout
          </button>
        </div>
      </div>

      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {renderContent()}
      </div>

    </div>
  );
}

const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '12px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const labelStyle = { display: 'block', marginBottom: '8px', color: '#475569', fontSize: '13px', fontWeight: 'bold' };
const readOnlyStyle = { padding: '12px 15px', backgroundColor: '#f1f5f9', borderRadius: '8px', color: '#334155', fontSize: '14px', border: '1px solid #e2e8f0' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', boxSizing: 'border-box' };
